import {WIDTH as W,HEIGHT as H,MAX_PLAYERS,FACTIONS,FACTION,BUILDING,STRIKE,clamp,index,point,dist} from './conquest-data.mjs';
const N=W*H;
export function neighbors(i){const x=i%W,y=Math.floor(i/W);return[i-W,i+1,i+W,i-1].filter((n,k)=>n>=0&&n<N&&(k!==1||x<W-1)&&(k!==3||x>0))}
function inside(x,y,poly){let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])hit=!hit}return hit}
const hash=(x,y)=>{let n=Math.imul(x+1,374761393)^Math.imul(y+11,668265263);n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967296};
export function createMap(region){const terrain=Array(N).fill(0),water=Array(N).fill(0);let land=0;for(let y=0;y<H;y++)for(let x=0;x<W;x++){const xx=(x+.5)/W,yy=(y+.5)/H;if(!region.polygons.some(p=>inside(xx,yy,p))||(region.lakes||[]).some(p=>inside(xx,yy,p)))continue;const mountain=(region.mountains||[]).some(m=>Math.hypot((xx-m.x)*W/H,yy-m.y)<m.r);terrain[index(x,y)]=mountain?3:hash(x,y)>.72?2:1;land++}let component=0;for(let i=0;i<N;i++){if(terrain[i]||water[i])continue;const queue=[i];water[i]=++component;for(let k=0;k<queue.length;k++)for(const n of neighbors(queue[k]))if(!terrain[n]&&!water[n]){water[n]=component;queue.push(n)}}const nearest=(x,y)=>{const start=index(clamp(x,0,W-1),clamp(y,0,H-1));if(terrain[start])return start;const q=[start],seen=new Set(q);for(let k=0;k<q.length;k++)for(const n of neighbors(q[k]))if(!seen.has(n)){if(terrain[n])return n;seen.add(n);q.push(n)}return 0};const cities=region.cities.map(c=>({...c,cell:nearest(c.x*W,c.y*H)}));for(const c of cities)terrain[c.cell]=4;const landComponents=Array(N).fill(0);let lc=0;for(let i=0;i<N;i++){if(!terrain[i]||landComponents[i])continue;const q=[i];landComponents[i]=++lc;for(let k=0;k<q.length;k++)for(const n of neighbors(q[k]))if(terrain[n]&&!landComponents[n]){landComponents[n]=lc;q.push(n)}}return{landComponents,coastCache:{},id:region.id,name:region.name,terrain,water,land,cities,spawns:region.spawn.map(p=>nearest(p.x*W,p.y*H))}}
export function rng(s){s.rng=(Math.imul(s.rng,1664525)+1013904223)>>>0;return s.rng/4294967296}
export const player=(s,id)=>s.players.find(p=>p.id===id);
export const ready=(s,b)=>b.complete<=s.time;
export const aliveBuildings=(s,id,kind)=>s.buildings.filter(b=>b.owner===id&&(!kind||b.kind===kind)&&ready(s,b));
export const allied=(s,a,b)=>a===b||s.pacts.some(p=>p.a===Math.min(a,b)&&p.b===Math.max(a,b)&&p.until>s.time);
export const embargoed=(s,a,b)=>s.embargo.some(e=>e.a===a&&e.b===b||e.a===b&&e.b===a);
export function log(s,text,kind='info',extra={}){s.log.push({id:++s.seq,time:s.time,text,kind,...extra});s.log=s.log.slice(-35)}
export function createGame(region,options={}){const map=createMap(region),s={version:1,id:options.id||'conquest-'+Date.now()+'-'+(options.seed||1),region:region.id,map,rng:(options.seed||Date.now())>>>0,players:[],owners:map.terrain.map(t=>t?0:-1),burn:Array(N).fill(0),buildings:[],orders:[],missions:[],rails:[],pacts:[],offers:[],embargo:[],log:[],time:0,startedAt:0,phase:'placement',paused:false,seq:0,revision:0,winners:[],limit:clamp(Number(options.limit)||1200,300,3600),target:.8,difficulty:clamp(Number(options.difficulty)||1,1,3)};const used=new Set(),humans=Array.isArray(options.humans)&&options.humans.length?options.humans.slice(0,4):[{pid:'local',name:'Dresseur',faction:options.faction||'aqua'}];const add=(h,ai)=>{let f=FACTIONS.find(f=>f.id===h.faction&&!used.has(f.id));if(!f)f=FACTIONS.find(f=>!used.has(f.id));used.add(f.id);s.players.push({id:s.players.length+1,pid:h.pid||'ai-'+f.id,name:String(h.name||f.name).slice(0,20),faction:f.id,ai,alive:true,deployed:false,home:null,land:0,balls:650,credits:1150,cap:1000,growth:0,income:0,traitorUntil:0,nextAI:7+rng(s)*5,nextBuild:10+rng(s)*4})};humans.forEach(h=>add(h,false));const count=clamp(Math.floor(Number(options.bots)??5),1,MAX_PLAYERS-humans.length);for(let i=0;i<(Number.isFinite(count)?count:5);i++)add({},true);return s}
function own(s,cell,id,destroy=false){const previous=s.owners[cell];if(previous===id)return;const old=player(s,previous),next=player(s,id);if(old)old.land--;if(next)next.land++;s.owners[cell]=id;s.revision++;const b=s.buildings.find(b=>b.cell===cell);if(b){if(destroy||id===0){s.buildings=s.buildings.filter(x=>x!==b)}else{b.owner=id;b.complete=s.time+2;log(s,FACTION(next.faction).name+' capture '+BUILDING(b.kind).name+'.','capture')}}}
export function deploy(s,id,cell){const p=player(s,id);if(s.phase!=='placement'||!p||p.deployed||!Number.isInteger(cell)||!s.map.terrain[cell]||s.owners[cell]!==0)return{ok:false,message:'Choisis un terrain libre pour ton QG.'};if(s.players.some(o=>o.deployed&&dist(point(o.home),point(cell))<10))return{ok:false,message:'Ce départ est trop proche d’une autre team.'};p.home=cell;p.deployed=true;const center=point(cell),queue=[cell],seen=new Set(queue);for(let k=0;k<queue.length;k++){const n=queue[k];if(s.owners[n]===0)own(s,n,id);for(const v of neighbors(n))if(!seen.has(v)&&s.map.terrain[v]&&s.owners[v]===0&&dist(center,point(v))<=4){seen.add(v);queue.push(v)}}s.buildings.push({id:++s.seq,owner:id,cell,kind:'city',level:1,complete:s.time,readyAt:s.time,nextTrade:s.time+8,hq:true});if(!p.ai&&s.players.filter(p=>!p.ai).every(p=>p.deployed))startPlaying(s);return{ok:true}}
function autoSpawn(s,id){const candidates=s.map.spawns.filter(c=>s.owners[c]===0).sort((a,b)=>{const score=c=>Math.min(...s.players.filter(p=>p.deployed).map(p=>dist(point(p.home),point(c))),999);return score(b)-score(a)});for(const c of candidates){if(deploy(s,id,c).ok)return}for(let i=0;i<N;i++)if(s.map.terrain[i]&&deploy(s,id,i).ok)return}
function startPlaying(s){if(s.phase!=='placement')return;for(const p of s.players.filter(p=>p.ai&&!p.deployed))autoSpawn(s,p.id);if(s.players.some(p=>!p.deployed))return;s.phase='playing';s.startedAt=s.time;log(s,'L’opération commence. Contrôle 80 % des terres, seul ou avec tes alliés.','start')}
export function coastCells(s,cell){if(s.map.coastCache[cell])return s.map.coastCache[cell];const p=point(cell),out=[];for(let y=Math.max(0,p.y-2);y<=Math.min(H-1,p.y+2);y++)for(let x=Math.max(0,p.x-2);x<=Math.min(W-1,p.x+2);x++){const i=index(x,y);if(!s.map.terrain[i])out.push(i)}s.map.coastCache[cell]=out;return out}
export function buildCost(s,id,kind){const def=BUILDING(kind);if(!def)return Infinity;const count=s.buildings.filter(b=>b.owner===id&&(kind==='port'||kind==='factory'?['port','factory'].includes(b.kind):b.kind===kind)).length;return Math.round(def.cost*Math.min(4,1.45**count))}
export function build(s,id,cell,kind){const p=player(s,id),def=BUILDING(kind),cost=buildCost(s,id,kind);if(!p?.alive||!def||s.phase!=='playing'||s.owners[cell]!==id||!s.map.terrain[cell])return{ok:false,message:'Construis sur ton territoire.'};if(s.burn[cell]>s.time)return{ok:false,message:'Cette zone doit se remettre de la perturbation élémentaire.'};if(s.buildings.some(b=>b.cell===cell))return{ok:false,message:'Ce terrain possède déjà un bâtiment.'};if(s.buildings.filter(b=>b.owner===id).length>=60)return{ok:false,message:'Limite de 60 bâtiments atteinte.'};if(def.coast&&!coastCells(s,cell).length)return{ok:false,message:'Une base maritime doit être placée près de l’eau.'};if(p.credits<cost)return{ok:false,message:'Pas assez de Pokédollars.'};p.credits-=cost;s.buildings.push({id:++s.seq,owner:id,cell,kind,level:1,complete:s.time+def.time,readyAt:s.time+def.time+(kind==='shrine'?8:0),nextTrade:s.time+def.time+6});log(s,FACTION(p.faction).name+' construit '+def.name+'.','build');return{ok:true}}
export function upgrade(s,id,buildingId){const b=s.buildings.find(b=>b.id===buildingId),p=player(s,id);if(!b||b.owner!==id||!ready(s,b)||b.level>=3)return{ok:false,message:'Amélioration indisponible.'};const cost=Math.round(BUILDING(b.kind).cost*b.level*.8);if(p.credits<cost)return{ok:false,message:'Pas assez de Pokédollars.'};p.credits-=cost;b.level++;b.complete=s.time+4;return{ok:true}}
export function defense(s,cell){const owner=s.owners[cell],p=player(s,owner),terrain=s.map.terrain[cell],weight=terrain===3?2.1:terrain===2?1.35:1;let base=p?2+p.balls/Math.max(30,p.land)*.6:2.5;for(const b of aliveBuildings(s,owner,'fort'))if(dist(point(cell),point(b.cell))<7+b.level*2)base*=1.9+b.level*.35;if(p?.traitorUntil>s.time)base*=.6;return base*weight*(s.burn[cell]>s.time?1.8:1)}
export function frontier(s,id,target,component=null){const out=[];for(let i=0;i<N;i++)if(s.owners[i]===target&&s.map.terrain[i]&&(!component||s.map.landComponents[i]===component)&&neighbors(i).some(n=>s.owners[n]===id))out.push(i);return out}
export function attack(s,id,cell,fraction=.3){const p=player(s,id),target=s.owners[cell];if(s.phase!=='playing'||!p?.alive||!Number.isInteger(cell)||!s.map.terrain[cell]||target===id)return{ok:false,message:'Vise une terre neutre ou une team voisine.'};if(target>0&&allied(s,id,target))return{ok:false,message:'Cette team est ton alliée. Romps d’abord le pacte.'};if(!frontier(s,id,target,s.map.landComponents[cell]).length)return{ok:false,message:'Pas de frontière commune. Utilise Lokhlass pour débarquer.'};if(s.orders.filter(o=>o.owner===id).length>=3)return{ok:false,message:'Trois fronts sont déjà engagés. Rappelle une escouade.'};fraction=Number(fraction);if(!Number.isFinite(fraction))return{ok:false,message:'Engagement invalide.'};const troops=Math.floor(p.balls*clamp(fraction,.05,1));if(troops<12)return{ok:false,message:'Il te faut au moins 12 Poké Balls pour une escouade.'};p.balls-=troops;s.orders.push({id:++s.seq,owner:id,target,component:s.map.landComponents[cell],focus:cell,left:troops,total:troops,last:p.home,age:0});return{ok:true}}
export function retreat(s,id,orderId){const p=player(s,id),o=s.orders.find(o=>o.id===orderId&&o.owner===id);if(!o||!p)return{ok:false,message:'Front introuvable.'};p.balls+=Math.floor(o.left*.85);s.orders=s.orders.filter(x=>x!==o);return{ok:true}}
export function path(s,start,end,water=false,allowed=()=>true){if(start===end)return[start];const prev=new Int32Array(N).fill(-1),queue=new Int32Array(N);let read=0,write=1;queue[0]=start;prev[start]=start;while(read<write){const i=queue[read++];for(const n of neighbors(i)){if(prev[n]!==-1||Boolean(s.map.terrain[n])===water||!allowed(n))continue;prev[n]=i;if(n===end){const result=[n];while(result.at(-1)!==start)result.push(prev[result.at(-1)]);return result.reverse()}queue[write++]=n}}return null}
function portPath(s,id,targetCell,foreignPort=false){const arrivals=coastCells(s,targetCell);for(const b of aliveBuildings(s,id,'port').sort((a,b)=>dist(point(a.cell),point(targetCell))-dist(point(b.cell),point(targetCell))))for(const start of coastCells(s,b.cell))for(const end of arrivals)if(s.map.water[start]===s.map.water[end]){const route=path(s,start,end,true);if(route)return{port:b,route}}return null}
export function transport(s,id,cell,fraction=.3){const p=player(s,id),target=s.owners[cell];if(s.phase!=='playing'||!p?.alive||!s.map.terrain[cell]||!coastCells(s,cell).length||target===id||target>0&&allied(s,id,target))return{ok:false,message:'Vise une côte neutre ou ennemie.'};const journey=portPath(s,id,cell);if(!journey)return{ok:false,message:'Aucune base maritime reliée à cette côte par la mer.'};fraction=Number(fraction);if(!Number.isFinite(fraction))return{ok:false,message:'Engagement invalide.'};const troops=Math.floor(p.balls*clamp(fraction,.05,1));if(troops<25)return{ok:false,message:'Réserve au moins 25 Poké Balls pour le débarquement.'};if(s.missions.filter(m=>m.owner===id&&m.kind==='transport').length>=6)return{ok:false,message:'Six escouades naviguent déjà.'};p.balls-=troops;s.missions.push({id:++s.seq,kind:'transport',owner:id,route:journey.route,target:cell,troops,progress:0,duration:Math.max(3,journey.route.length*.1),hp:70,level:1});return{ok:true}}
export function patrol(s,id,cell,shipId=null){const p=player(s,id);if(s.phase!=='playing'||!p?.alive||!Number.isInteger(cell)||s.map.terrain[cell]!==0)return{ok:false,message:'Vise une zone d’eau.'};const existing=s.missions.find(m=>m.id===shipId&&m.owner===id&&m.kind==='patrol');if(existing){const pos=missionPosition(existing),start=index(pos.x,pos.y),route=path(s,start,cell,true);if(!route)return{ok:false,message:'Cette mer est inaccessible.'};existing.route=route;existing.duration=Math.max(2,route.length*.1);existing.progress=0;existing.target=cell;return{ok:true}}if(p.credits<600)return{ok:false,message:'Une patrouille coûte 600 Pokédollars.'};if(s.missions.filter(m=>m.kind==='patrol'&&m.owner===id).length>=8)return{ok:false,message:'Huit patrouilles sont déjà déployées.'};const ports=aliveBuildings(s,id,'port');let journey;for(const port of ports)for(const start of coastCells(s,port.cell))if(s.map.water[start]===s.map.water[cell]){const route=path(s,start,cell,true);if(route){journey={port,route};break}}if(!journey)return{ok:false,message:'Construis une base maritime sur cette mer.'};p.credits-=600;s.missions.push({id:++s.seq,kind:'patrol',owner:id,route:journey.route,target:cell,progress:0,duration:Math.max(2,journey.route.length*.1),hp:150,level:1,kills:0,nextAttack:s.time+1});return{ok:true}}
export function missionPosition(m){if(m.route){const t=clamp(m.progress,0,1)*(m.route.length-1),i=Math.floor(t),a=point(m.route[i]),b=point(m.route[Math.min(i+1,m.route.length-1)]);return{x:a.x+(b.x-a.x)*(t-i),y:a.y+(b.y-a.y)*(t-i)}}const a=point(m.from),b=point(m.target);return{x:a.x+(b.x-a.x)*m.progress,y:a.y+(b.y-a.y)*m.progress}}
export function launch(s,id,cell,tier='signature'){const p=player(s,id),def=STRIKE(tier),owner=s.owners[cell];if(s.phase!=='playing'||!p?.alive||!def||!s.map.terrain[cell]||owner===id||owner>0&&allied(s,id,owner))return{ok:false,message:'Vise une terre neutre ou ennemie.'};if(tier==='constellation'&&owner<=0)return{ok:false,message:'L’assaut multiple doit cibler une team.'};const shrine=aliveBuildings(s,id,'shrine').filter(b=>b.level>=def.level&&b.readyAt<=s.time).sort((a,b)=>dist(point(a.cell),point(cell))-dist(point(b.cell),point(cell)))[0];if(!shrine)return{ok:false,message:'Sanctuaire insuffisant ou légendaire en recharge.'};if(p.credits<def.cost)return{ok:false,message:'Pas assez de Pokédollars pour cet assaut.'};p.credits-=def.cost;shrine.readyAt=s.time+Math.max(12,40-shrine.level*7);let targets=[cell];if(tier==='constellation'){const candidates=s.owners.flatMap((o,i)=>o===owner?[i]:[]);const bag=candidates.filter(i=>i!==cell);for(let i=0;i<4;i++)targets.push(bag.length?bag.splice(Math.floor(rng(s)*bag.length),1)[0]:cell)}for(const target of targets)s.missions.push({id:++s.seq,kind:'legend',owner:id,from:shrine.cell,target,tier,legend:FACTION(p.faction).legend,armor:def.power,radius:def.radius,progress:0,duration:4+dist(point(shrine.cell),point(target))*.04});log(s,FACTION(p.faction).name+' envoie '+FACTION(p.faction).legendName+' !','legend',{owner:id,target:cell});return{ok:true}}
export function diplomacy(s,id,otherId,action,resource='credits'){const p=player(s,id),other=player(s,otherId);if(s.phase!=='playing'||!p?.alive||!other?.alive||id===otherId)return{ok:false,message:'Choisis une autre team active.'};if(action==='alliance'){if(allied(s,id,otherId))return{ok:false,message:'Vous êtes déjà alliés.'};if(s.pacts.filter(x=>x.until>s.time&&(x.a===id||x.b===id)).length>=2)return{ok:false,message:'Tu peux maintenir deux pactes à la fois.'};if(s.pacts.filter(x=>x.until>s.time&&(x.a===otherId||x.b===otherId)).length>=2)return{ok:false,message:'Cette team possède déjà deux pactes.'};const offer=s.offers.find(o=>o.from===otherId&&o.to===id);if(offer||other.ai&&rng(s)>.15){s.offers=s.offers.filter(o=>!(o.from===otherId&&o.to===id||o.from===id&&o.to===otherId));s.pacts.push({a:Math.min(id,otherId),b:Math.max(id,otherId),until:s.time+180});log(s,FACTION(p.faction).name+' et '+FACTION(other.faction).name+' signent un pacte de 3 minutes.','alliance');return{ok:true}}if(other.ai)return{ok:false,message:'Cette team refuse le pacte pour le moment.'};if(!s.offers.some(o=>o.from===id&&o.to===otherId))s.offers.push({from:id,to:otherId,until:s.time+45});return{ok:true,message:'Proposition envoyée.'}}if(action==='reject'){s.offers=s.offers.filter(o=>!(o.from===otherId&&o.to===id));return{ok:true}}if(action==='betray'){if(!allied(s,id,otherId))return{ok:false,message:'Aucun pacte à rompre.'};s.pacts=s.pacts.filter(o=>!(o.a===Math.min(id,otherId)&&o.b===Math.max(id,otherId)));p.traitorUntil=s.time+45;s.embargo.push({a:id,b:otherId});log(s,FACTION(p.faction).name+' trahit son pacte ! Défense affaiblie pendant 45 s.','betrayal');return{ok:true}}if(action==='embargo'){const exists=s.embargo.find(o=>o.a===id&&o.b===otherId);if(exists)s.embargo=s.embargo.filter(o=>o!==exists);else s.embargo.push({a:id,b:otherId});return{ok:true}}if(action==='donate'){if(!['credits','balls'].includes(resource))return{ok:false,message:'Ressource invalide.'};const amount=Math.floor(p[resource]*.2);if(amount<10)return{ok:false,message:'Réserve insuffisante pour un don.'};p[resource]-=amount;other[resource]+=amount;log(s,FACTION(p.faction).name+' aide '+FACTION(other.faction).name+'.','gift');return{ok:true}}return{ok:false,message:'Action inconnue.'}}
export function command(s,id,c){if(!c||typeof c.kind!=='string'||s.phase==='finished'||s.paused)return{ok:false,message:'L’opération est en pause ou terminée.'};if(c.kind==='ping'){const p=player(s,id);if(!p||!Number.isInteger(c.cell)||c.cell<0||c.cell>=N||(p.nextPing||0)>s.time)return{ok:false,message:'Attends quelques secondes avant un nouveau signal.'};p.nextPing=s.time+3;log(s,FACTION(p.faction).name+' signale une position.','ping',{owner:id,cell:c.cell});return{ok:true}}if(c.kind==='spawn')return deploy(s,id,c.cell);if(c.kind==='attack')return attack(s,id,c.cell,c.fraction);if(c.kind==='build')return build(s,id,c.cell,c.building);if(c.kind==='upgrade')return upgrade(s,id,c.buildingId);if(c.kind==='retreat')return retreat(s,id,c.orderId);if(c.kind==='transport')return transport(s,id,c.cell,c.fraction);if(c.kind==='patrol')return patrol(s,id,c.cell,c.shipId);if(c.kind==='legend')return launch(s,id,c.cell,c.tier);if(c.kind==='diplomacy')return diplomacy(s,id,c.other,c.action,c.resource);return{ok:false,message:'Ordre inconnu.'}}
function conquerStep(s,o,dt){o.age+=dt;const p=player(s,o.owner);if(!p?.alive||o.target>0&&allied(s,o.owner,o.target)){o.done=true;return}let cells=frontier(s,o.owner,o.target,o.component);const focus=point(o.focus);cells.sort((a,b)=>dist(point(a),focus)-dist(point(b),focus));if(!cells.length){o.done=true;return}const rate=clamp(Math.floor(6+s.difficulty*(p.ai?2:0)),4,12);let taken=0;for(const cell of cells){if(taken>=rate)break;const cost=defense(s,cell);if(o.left<cost){o.done=true;break}o.left-=cost;const enemy=player(s,s.owners[cell]);if(enemy)enemy.balls=Math.max(0,enemy.balls-cost*.4);own(s,cell,o.owner);o.last=cell;taken++}if(o.left<2||o.age>60)o.done=true}
function economy(s,dt){for(const p of s.players){if(!p.deployed)continue;p.alive=p.land>0;if(!p.alive)continue;const buildings=aliveBuildings(s,p.id),levels=kind=>buildings.filter(b=>b.kind===kind).reduce((n,b)=>n+b.level,0);p.cap=Math.floor(900+p.land*2.5+levels('city')*650);p.growth=(8+Math.sqrt(p.land)*1.6+levels('city')*5+levels('factory')*18)*Math.max(.04,1-p.balls/p.cap);p.income=6+p.land*.035+levels('factory')+levels('city')*1.5;p.balls=Math.min(p.cap,p.balls+p.growth*dt);p.credits=Math.min(1e7,p.credits+p.income*dt)}}
function tradeStep(s){for(const b of s.buildings){if(!ready(s,b)||b.nextTrade>s.time||!['factory','port'].includes(b.kind)||!player(s,b.owner)?.alive)continue;b.nextTrade=s.time+Math.max(4,14-b.level*2);if(b.kind==='port'){const starts=coastCells(s,b.cell);const ports=s.buildings.filter(o=>o.kind==='port'&&ready(s,o)&&o.owner!==b.owner&&!embargoed(s,b.owner,o.owner));ports.sort((a,c)=>dist(point(a.cell),point(b.cell))-dist(point(c.cell),point(b.cell)));let spawned=false;for(const dest of ports){for(const a of starts)for(const z of coastCells(s,dest.cell))if(!spawned&&s.map.water[a]===s.map.water[z]){const route=path(s,a,z,true);if(route){s.missions.push({id:++s.seq,kind:'trade',owner:b.owner,recipient:dest.owner,target:dest.cell,route,progress:0,duration:Math.max(3,route.length*.12),reward:Math.round(40+route.length*1.8)*b.level,hp:40});spawned=true}}if(spawned)break}}else{const candidates=s.buildings.filter(o=>o.id!==b.id&&ready(s,o)&&['city','port','factory'].includes(o.kind)&&allied(s,b.owner,o.owner)&&!embargoed(s,b.owner,o.owner));candidates.sort((a,c)=>dist(point(a.cell),point(b.cell))-dist(point(c.cell),point(b.cell)));for(const dest of candidates){const route=path(s,b.cell,dest.cell,false,i=>s.owners[i]===b.owner||allied(s,b.owner,s.owners[i]));if(route){if(!s.rails.some(r=>r.from===b.id&&r.to===dest.id||r.from===dest.id&&r.to===b.id))s.rails.push({from:b.id,to:dest.id,owner:b.owner,route});s.rails=s.rails.slice(-100);s.missions.push({id:++s.seq,kind:'train',owner:b.owner,recipient:dest.owner,target:dest.cell,route,progress:0,duration:Math.max(3,route.length*.1),reward:(35+route.length)*b.level,hp:30});break}}}}}
function impact(s,m){const center=point(m.target),def=STRIKE(m.tier);for(let y=Math.max(0,Math.floor(center.y-m.radius));y<=Math.min(H-1,center.y+m.radius);y++)for(let x=Math.max(0,Math.floor(center.x-m.radius));x<=Math.min(W-1,center.x+m.radius);x++){const cell=index(x,y),owner=s.owners[cell];if(!s.map.terrain[cell]||dist(center,{x,y})>m.radius||owner===m.owner||owner>0&&allied(s,m.owner,owner))continue;const enemy=player(s,owner);if(enemy)enemy.balls=Math.max(0,enemy.balls-12*def.power);own(s,cell,0,true);s.burn[cell]=s.time+28}log(s,FACTION(player(s,m.owner).faction).legendName+' déchaîne sa puissance !','impact',{owner:m.owner,cell:m.target,radius:m.radius,type:FACTION(player(s,m.owner).faction).type});for(const ship of s.missions)if(['trade','transport','patrol'].includes(ship.kind)&&!allied(s,m.owner,ship.owner)&&dist(center,missionPosition(ship))<=m.radius)ship.done=true;s.revision++}
function missionsStep(s,dt){for(const m of s.missions){if(m.done)continue;m.progress=clamp(m.progress+dt/m.duration,0,1);const pos=missionPosition(m);if(m.kind==='legend'){for(const b of s.buildings){if(b.kind!=='shield'||!ready(s,b)||b.readyAt>s.time||allied(s,m.owner,b.owner))continue;const range=10+b.level*5;if(dist(pos,point(b.cell))>range)continue;b.readyAt=s.time+Math.max(2,9-b.level*2);m.armor-=b.level;log(s,'Une station Gardevoir intercepte '+FACTION(player(s,m.owner).faction).legendName+'.','intercept',{from:b.cell,x:pos.x,y:pos.y,owner:b.owner});if(m.armor<=0){m.done=true;break}}if(m.progress>=1&&!m.done){impact(s,m);m.done=true}}else if(m.kind==='patrol'){if(m.nextAttack<=s.time){m.nextAttack=s.time+1.7;const enemies=s.missions.filter(o=>o!==m&&!o.done&&['trade','transport','patrol'].includes(o.kind)&&!allied(s,m.owner,o.owner)&&dist(pos,missionPosition(o))<5+m.level).sort((a,b)=>a.kind==='patrol'?-1:1);const enemy=enemies[0];if(enemy){enemy.hp-=32+m.level*10;log(s,'Léviator engage une cible maritime.','naval',{x:pos.x,y:pos.y,tx:missionPosition(enemy).x,ty:missionPosition(enemy).y,owner:m.owner});if(enemy.hp<=0){enemy.done=true;m.kills++;m.level=Math.min(3,1+Math.floor(m.kills/2));player(s,m.owner).credits+=enemy.reward||80}}}if(aliveBuildings(s,m.owner,'port').some(b=>dist(pos,point(b.cell))<5))m.hp=Math.min(130+m.level*30,m.hp+dt*14)}else if(m.progress>=1){m.done=true;if(m.kind==='transport'){const owner=s.owners[m.target];if(owner!==m.owner&&!allied(s,m.owner,owner)&&m.troops>defense(s,m.target)){m.troops-=defense(s,m.target);own(s,m.target,m.owner);s.orders.push({id:++s.seq,owner:m.owner,target:owner,component:s.map.landComponents[m.target],focus:m.target,left:m.troops,total:m.troops,last:m.target,age:0});log(s,'Lokhlass établit une tête de pont.','landing',{owner:m.owner,cell:m.target})}else if(owner===m.owner)player(s,m.owner).balls+=m.troops}else if(!embargoed(s,m.owner,m.recipient)&&player(s,m.owner)?.alive&&player(s,m.recipient)?.alive&&s.owners[m.target]===m.recipient){player(s,m.owner).credits+=m.reward;player(s,m.recipient).credits+=m.owner===m.recipient?0:Math.floor(m.reward*.6)}}}s.missions=s.missions.filter(m=>!m.done).slice(-180)}
function aiStep(s){for(const p of s.players.filter(p=>p.ai&&p.alive)){if(p.nextAI<=s.time){p.nextAI=s.time+(6+rng(s)*7)/(.75+s.difficulty*.25);const neutral=frontier(s,p.id,0);const borders=s.players.filter(o=>o.id!==p.id&&o.alive&&!allied(s,p.id,o.id)).flatMap(o=>frontier(s,p.id,o.id));const pool=neutral.length&&rng(s)<.75?neutral:borders.length?borders:neutral;if(pool.length)attack(s,p.id,pool[Math.floor(rng(s)*pool.length)],.25+rng(s)*.35);else if(aliveBuildings(s,p.id,'port').length){const shores=s.owners.flatMap((o,i)=>s.map.terrain[i]&&o!==p.id&&!allied(s,p.id,o)&&coastCells(s,i).length?[i]:[]);for(let k=0;k<5&&shores.length;k++){if(transport(s,p.id,shores[Math.floor(rng(s)*shores.length)],.4).ok)break}}if(aliveBuildings(s,p.id,'shrine').length&&p.credits>1200&&borders.length)launch(s,p.id,borders[Math.floor(rng(s)*borders.length)],p.credits>3000&&rng(s)>.5?'cataclysm':'signature')}
 if(p.nextBuild<=s.time){p.nextBuild=s.time+6+rng(s)*7;const ownCells=s.owners.flatMap((o,i)=>o===p.id&&!s.buildings.some(b=>b.cell===i)?[i]:[]);let kind=p.land>150&&p.credits>1800&&!aliveBuildings(s,p.id,'shrine').length?'shrine':rng(s)<.35?'city':rng(s)<.65?'factory':'fort';if(p.credits>2500&&rng(s)<.45)kind='shield';if(!aliveBuildings(s,p.id,'port').length&&ownCells.some(i=>coastCells(s,i).length)&&rng(s)<.45)kind='port';const choices=kind==='port'?ownCells.filter(i=>coastCells(s,i).length):ownCells;if(choices.length)build(s,p.id,choices[Math.floor(rng(s)*choices.length)],kind);const up=s.buildings.find(b=>b.owner===p.id&&ready(s,b)&&b.level<3&&(b.kind==='shrine'||rng(s)>.8));if(up&&p.credits>1600)upgrade(s,p.id,up.id)}
 }}
function winners(s){const active=s.players.filter(p=>p.alive);if(!active.length)return[];for(const p of active){const group=active.filter(o=>allied(s,p.id,o.id));if(group.reduce((n,p)=>n+p.land,0)/s.map.land>=s.target)return group.map(p=>p.id)}if(active.length===1)return[active[0].id];if(s.time-s.startedAt>=s.limit)return[active.slice().sort((a,b)=>b.land-a.land||b.credits-a.credits)[0].id];return[]}
export function step(s,dt=.25){if(s.paused||s.phase==='finished')return;dt=clamp(Number(dt)||.25,.01,1);s.time+=dt;if(s.phase==='placement'){if(s.time>=20){for(const p of s.players.filter(p=>!p.ai&&!p.deployed))autoSpawn(s,p.id);if(s.phase==='placement')startPlaying(s)}return}s.pacts=s.pacts.filter(p=>p.until>s.time);s.offers=s.offers.filter(o=>o.until>s.time);economy(s,dt);aiStep(s);for(const o of s.orders)conquerStep(s,o,dt);for(const o of s.orders.filter(o=>o.done)){const p=player(s,o.owner);if(p?.alive)p.balls+=Math.max(0,o.left)}s.orders=s.orders.filter(o=>!o.done);missionsStep(s,dt);if(Math.floor(s.time*4)%4===0)tradeStep(s);const win=winners(s);if(win.length){s.phase='finished';s.winners=win;log(s,'La campagne est terminée.','victory')}return s}
export function rle(values){const out=[];let last=values[0],count=0;for(const n of values){if(n===last&&count<65535)count++;else{out.push(last,count);last=n;count=1}}out.push(last,count);return out}
export function unrle(data,length=N){if(!Array.isArray(data)||data.length>length*2||data.length%2)throw Error('Données de carte invalides');const out=[];for(let i=0;i<data.length;i+=2){const value=data[i],count=data[i+1];if(!Number.isFinite(value)||!Number.isInteger(count)||count<1||out.length+count>length)throw Error('Données de carte invalides');for(let j=0;j<count;j++)out.push(value)}if(out.length!==length)throw Error('Données de carte incomplètes');return out}
export function snapshot(s){const {map,owners,burn,...rest}=s;return{...structuredClone(rest),owners:rle(owners),burn:rle(burn)}}
export function restore(region,data){if(data?.version!==1||data.region!==region.id||!Array.isArray(data.players)||data.players.length<2||data.players.length>MAX_PLAYERS)throw Error('Sauvegarde de Conquête incompatible');const owners=unrle(data.owners),burn=unrle(data.burn);if(owners.some(n=>!Number.isInteger(n)||n< -1||n>data.players.length))throw Error('Territoires invalides');return{...structuredClone(data),map:createMap(region),owners,burn,rails:Array.isArray(data.rails)?data.rails:[]}}
